// tempDoc writes a document to a temp file for --file inputs.
func tempDoc(t *testing.T, content string) string {
	t.Helper()
	path := t.TempDir() + "/body.yml"
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
	return path
}

func mustJSON(t *testing.T, v any) string {
	t.Helper()
	raw, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return string(raw)
}

func TestParseDocumentAcceptsYAMLAndJSON(t *testing.T) {
	yamlDoc, err := parseDocument("spec", "name: x\ncount: 12345678901234567890\n")
	if err != nil {
		t.Fatal(err)
	}
	if got := mustJSON(t, yamlDoc); got != `{"count":12345678901234567890,"name":"x"}` {
		t.Fatalf("yaml: %s", got)
	}
	jsonDoc, err := parseDocument("spec", `{"a": [1, 2]}`)
	if err != nil {
		t.Fatal(err)
	}
	if got := mustJSON(t, jsonDoc); got != `{"a":[1,2]}` {
		t.Fatalf("json: %s", got)
	}
	for _, bad := range []string{"", "null", "~"} {
		if _, err := parseDocument("spec", bad); err == nil {
			t.Fatalf("%q must be rejected", bad)
		}
	}
	if _, err := objectArg("spec", "just a string"); err == nil || !strings.Contains(err.Error(), "expected an object") {
		t.Fatalf("scalar for an object input: %v", err)
	}
}

