func TestFinishReportsDeepestRequiredPathsByFlag(t *testing.T) {
	schema := parseBodySchema(testSchema)
	flagFor := map[string]string{"metadata.name": "--name", "spec.adapter": "--adapter", "spec.adapter.mcp.url": "--mcp-url"}
	b := newBodyBuilder()
	err := b.finish(schema, flagFor, false)
	if err == nil || err.Error() != "required flag(s) not set: --name, --adapter" {
		t.Fatalf("empty body: %v", err)
	}
	b = newBodyBuilder()
	_ = b.set("name", []string{"metadata", "name"}, "n")
	_ = b.applyUnionFlag(adapterUnion(), "mcp", nil, false)
	_ = b.resolveUnion(adapterUnion())
	err = b.finish(schema, flagFor, false)
	if err == nil || err.Error() != "required flag(s) not set: --mcp-url" {
		t.Fatalf("arm required leaf: %v", err)
	}
	_ = b.set("mcp-url", []string{"spec", "adapter", "mcp", "url"}, "u")
	if err := b.finish(schema, flagFor, false); err != nil {
		t.Fatalf("complete body: %v", err)
	}
	// A required object with no required leaves is sent as {} rather than
	// demanded from the user.
	relaxed := parseBodySchema(strings.Replace(testSchema, `"Mcp": {"type": "object", "required": ["url"],`, `"Mcp": {"type": "object",`, 1))
	b = newBodyBuilder()
	_ = b.set("name", []string{"metadata", "name"}, "n")
	_ = b.applyUnionFlag(adapterUnion(), "mcp", nil, false)
	_ = b.resolveUnion(adapterUnion())
	if err := b.finish(relaxed, flagFor, false); err != nil {
		t.Fatalf("required object without required leaves: %v", err)
	}
	if got := mustJSON(t, b.body); got != `{"metadata":{"name":"n"},"spec":{"adapter":{"mcp":{},"type":"mcp"}}}` {
		t.Fatal(got)
	}
	// Optional envelopes (a patch) impose nothing when absent.
	patch := parseBodySchema(strings.Replace(testSchema, `"required": ["metadata", "spec"],`, "", 1))
	if err := newBodyBuilder().finish(patch, flagFor, false); err != nil {
		t.Fatalf("patch: %v", err)
	}
}

func TestWholeBodyDocumentsUseTheSameValidation(t *testing.T) {
	schema := parseBodySchema(`{
	  "type":"array",
	  "items":{"type":"object","required":["season"],"properties":{
	    "season":{"type":"string","enum":["SEASON_SPRING"],"enumShort":{"spring":"SEASON_SPRING"}}
	  }}
	}`)
	b := newBodyBuilder()
	raw, err := b.applyRootDocument("file", tempDoc(t, `[{"season":"spring","junk":true}]`), true, schema, false)
	if err != nil {
		t.Fatal(err)
	}
	raw, err = b.finishValue(schema, raw, nil, false)
	if err != nil {
		t.Fatal(err)
	}
	if got := mustJSON(t, raw); got != `[{"season":"SEASON_SPRING"}]` {
		t.Fatalf("validated whole-body list: %s", got)
	}
	if _, err := b.finishValue(schema, []any{map[string]any{}}, nil, false); err == nil || !strings.Contains(err.Error(), "0.season") {
		t.Fatalf("required field in whole-body list: %v", err)
	}

	enumSchema := parseBodySchema(`{"type":"string","enum":["MODE_FAST"],"enumShort":{"fast":"MODE_FAST"}}`)
	value, err := b.finishValue(enumSchema, "FAST", nil, false)
	if err != nil || value != "MODE_FAST" {
		t.Fatalf("root enum: %v %v", value, err)
	}
}

